CREATE OR REPLACE FUNCTION calculate_tes(p_tx_key bigint)
RETURNS numeric AS $$
DECLARE
    v_eng text;
    v_score numeric;
BEGIN
    -- Get the engagement rating for this treatment
    SELECT th_eng INTO v_eng FROM treatmentbasics WHERE tx_key = p_tx_key;

    -- Map engagement to score: High=3, Medium=2, Low=1
    CASE v_eng
        WHEN 'High' THEN v_score := 3;
        WHEN 'Medium' THEN v_score := 2;
        WHEN 'Low' THEN v_score := 1;
        ELSE v_score := NULL;
    END CASE;

    RETURN v_score;
END;
$$ LANGUAGE plpgsql;

